starterCode.css:
body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; background: #eef2f6; color: #172033; }
main { max-width: 920px; margin: auto; }
header { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
button { padding: 9px 14px; border: 0; border-radius: 6px; background: #2563eb; color: white; }
#pedidos { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; margin-top: 16px; }
.pedido { padding: 14px; border: 1px solid #d7dee9; border-radius: 8px; background: white; }
.completado { border-color: #16a34a; }

